    for (const t of [0.35, 0.65]) lineRingP(B.p(RIB), Q.map(q => [lerp(q[0], c[0], t), lerp(q[1], c[1], t)]), lerp(y1 + 0.4, yR, Math.pow(t, 0.85)), 0.22, 3);
