// =====================================================================================================================
// Medium-detail towers on their LandsD rings (tower / podium pieces with LandsD base and top levels, rev. 2026-10-20). Facade colours,
// mullion / pier rhythm and roof furniture are approximations unless a source is named.
// =====================================================================================================================
// generic office tower key: podium rings + tower ring(s), all from LandsD levels
function officeKey(k, o){
  const dk = o.dk || k, c = o.c || null;
  LANDMARKS[k] = Object.assign({zh:o.zh, en:o.en, cat:'new', r:o.r, h:o.h, lt:{m:1, c:o.lc || '#e2ecff', k:0.6}}, o.nolabel ? {label:false} : {}, {
    build(){
      const g = new THREE.Group(), B = mkB(), Z = mkZ(dk, o.ref, c), T = {}; for (const n in D[dk]) T[n] = c ? shiftP(D[dk][n], -c[0], -c[1]) : D[dk][n];
      for (const cl of (o.clip ? (Array.isArray(o.clip[0]) ? o.clip : [o.clip]) : [])) for (const n in T) T[n] = clipP(T[n], cl[0], cl[1], cl[2] + (c ? cl[0]*c[0] + cl[1]*c[1] : 0));
      for (const nm of o.pods || []){ const P = o.podClip ? clipP(T[nm], ...o.podClip) : T[nm], y0 = Z.base(nm), y1 = Z.top(nm); found(B, '#8e8a84', P, Z, y0); podT(B, P, y0, y1, {w:o.pw || '#b8b2a8', g:o.pg || {c:'#4f5a60', m:1}}); roofT(B, P, y1, {par:o.pw || '#b8b2a8', ph:0.9}); }
      for (const tw of o.tws){ const P = T[tw.nm], yb = tw.yb !== undefined ? Z.y(tw.yb) : Z.base(tw.nm), y1 = Z.top(tw.top || tw.nm), Q = tw.off ? offO(P, tw.off) : P;
        found(B, '#8e8a84', P, Z, yb);
        towerT(B, Q, yb, y1, tw.t);
        if (tw.crown) tw.crown(B, g, Q, y1, Z); else roofT(B, Q, y1, {par:tw.t.par || tw.t.sb || '#9a9a96', ph:1.4, plant:tw.t.plant || '#8f918f', ins:3.5, plh:4.5}); }
      B.flush(g); return g; }});
  if (c) placeSub(k, dk, c); else place(k, ...TGT[k]);
}

// 9 Queen's Road Central / The Galleria (1991; Wikipedia: roof 187 m, 39 floors). LandsD ring with the serrated ("stepped") corners, base 3.7,
