// Residential towers (Kennedy Town / Mid-Levels). LandsD rings and levels; bay-window relief and colours approximate.
// =====================================================================================================================
function resiT(B, P, y0, y1, o, rng){
  prismP(B.p(o.w), P, y0, y1, true);
  floorsP(B.p(o.g), P, y0 + 0.9, y1 - 0.6, o.fh || 3.15, o.gh || 1.7, 0.07);
  if (o.ac) acP(B.p(o.ac), P, y0, y1, o.fh || 3.15, 3.2, rng, 0.35);
  if (o.st) mullP(B.p(o.st), P, y0, y1, o.sp || 5.5, 0.5, 0.12, null, 0.35);
  flatP(B.p('#8f8f8c'), P, y1);
}
function resiKey(k, o){
  const dk = o.dk || k, c = o.c || null;
  LANDMARKS[k] = Object.assign({zh:o.zh, en:o.en, cat:'new', r:o.r, h:o.h, lt:{m:1, c:'#ffe6c4', k:0.6}}, o.nolabel ? {label:false} : {}, {
    build(){
      const g = new THREE.Group(), B = mkB(), Z = mkZ(dk, o.ref, c), T = {}, rng = LMCTX.rng; for (const n in D[dk]) T[n] = c ? shiftP(D[dk][n], -c[0], -c[1]) : D[dk][n];
      for (const nm of o.pods || []){ const P = o.podClip ? clipP(T[nm], ...o.podClip) : T[nm], y0 = Z.base(nm), y1 = Z.top(nm); found(B, '#8e8a84', P, Z, y0); if (o.podPlain){ prismP(B.p(o.pw), P, y0, y1); floorsP(B.p('#4a4d4f'), P, y0 + 1.2, y1 - 0.8, 3.2, 1.0, 0.07); } else podT(B, P, y0, y1, {w:o.pw, g:{c:'#4d585e', m:1}}); flatP(B.p('#7f8f78'), offO(P, -1), y1 + 0.05); parP(B.p(o.pw), P, y1, 1.1, 0.25); }
      for (const tw of o.tws){ const P = T[tw.nm], yb = tw.yb !== undefined ? Z.y(tw.yb) : Z.base(tw.nm), y1 = Z.top(tw.nm);
        found(B, '#8e8a84', P, Z, yb);
        resiT(B, P, yb, y1, o.t, rng);
        if (o.crown) o.crown(B, g, P, y1, Z); else { parP(B.p(o.t.st || o.t.w), P, y1, 1.4, 0.3); const Q = offO(P, -2.5); if (Math.abs(area2(Q)) > 30) prismP(B.p(o.t.w), Q, y1, y1 + 5.5); } }
      B.flush(g); return g; }});
  if (c) placeSub(k, dk, c); else place(k, ...TGT[k]);
}
