const FDN = '#9b968c';
// Pedder Building, 12 Pedder Street (completed 1924; nine storeys plus mezzanine and basement, 35 m above street level; Beaux-Arts with
// neo-classical columns, arches, mouldings and medallions; stone-clad base with three main entrance arches; a pediment and a top balcony
// level; Wikipedia). LandsD ring: base 5.5 top 43.8 mPD (38.3 m). Render colour and window rhythm approximate.
LANDMARKS.hkpedder = {zh:'毕打行', en:'Pedder Building', cat:'old', r:28, h:39,
  lt:{m:0, c:'#ffe2b8', k:0.9, e:0.45, anim:'breathe'},
  build(){
    const g = new THREE.Group(), B = mkB(), Z = mkZ('hkpedder', 'p'), P = D.hkpedder.p, y0 = Z.g0, y1 = Z.top('p');
    const ST = '#b4ab9c', WL = '#d9c9a6', TR = '#efe6d2', GLW = {c:'#3f4a4e', glow:'#ffdcae', gk:0.5};
    found(B, FDN, P, Z, y0);
    prismP(B.p(ST), P, y0, y0 + 9.5, true); prismP(B.p(WL), P, y0 + 9.5, y1 - 2.2, true);
    winsP(B.p(GLW), P, y0 + 10.5, y1 - 7.5, 3.6, 2.4, 1.3, 2.2, 0.05);
    mullP(B.p(TR), P, y0 + 9.5, y1 - 6.6, 4.8, 0.7, 0.1, null, 0.35);
    for (const y of [y0 + 9.5, y1 - 6.6]) prismP(B.p(TR), offO(P, 0.45), y, y + 0.6);
    // the top balcony level and the two upper floors, cornice
    const i = edgeTo(P, 0.6, 0.8, 10), [a, b] = E(P, i), [nx, nz] = outN(P, i), L = Math.hypot(b[0]-a[0], b[1]-a[1]), ry = -Math.atan2(b[1]-a[1], b[0]-a[0]), ux = (b[0]-a[0])/L, uz = (b[1]-a[1])/L;
    balP(B.p(TR), [a[0] + nx*0.9, a[1] + nz*0.9], [b[0] + nx*0.9, b[1] + nz*0.9], y1 - 6.0, 1.0, 0.45); boxP(B.p(TR), L, 0.3, 1.0, (a[0]+b[0])/2 + nx*0.5, y1 - 6.3, (a[1]+b[1])/2 + nz*0.5, ry);
    winsP(B.p(GLW), P, y1 - 5.6, y1 - 2.6, 3.0, 2.4, 1.2, 2.0, 0.05);
    prismP(B.p(TR), offO(P, 0.5), y1 - 2.2, y1 - 1.4); prismP(B.p(WL), P, y1 - 1.4, y1); flatP(B.p('#8e8a84'), P, y1);
    // front on Pedder Street: three entrance arches in the stone base, a pediment over the centre
    const m = [(a[0]+b[0])/2, (a[1]+b[1])/2];
    for (const s of [-L*0.22, 0, L*0.22]){ const q = [m[0] + ux*s + nx*0.08, m[1] + uz*s + nz*0.08]; boxP(B.p('#3b3a37'), 3.2, 5.6, 0.2, q[0], y0, q[1], ry);
      const o = B.p(TR); for (let k = 0; k < 6; k++){ const t0 = k/6*PI, t1 = (k+1)/6*PI; const p0 = [q[0] - ux*Math.cos(t0)*1.9 + nx*0.12, y0 + 5.6 + Math.sin(t0)*1.9, q[1] - uz*Math.cos(t0)*1.9 + nz*0.12], p1 = [q[0] - ux*Math.cos(t1)*1.9 + nx*0.12, y0 + 5.6 + Math.sin(t1)*1.9, q[1] - uz*Math.cos(t1)*1.9 + nz*0.12]; segP(o, p0, p1, 0.22, 4); } }
    { const o = B.p(TR), w = L*0.3, yb = y1 - 1.4, P0 = [m[0] - ux*w + nx*0.6, yb, m[1] - uz*w + nz*0.6], P1 = [m[0] + ux*w + nx*0.6, yb, m[1] + uz*w + nz*0.6], P2 = [m[0] + nx*0.6, yb + 2.8, m[1] + nz*0.6];
      triP(o, P0, P1, P2); const Bk = [P0, P1, P2].map(p => [p[0] - nx*0.9, p[1], p[2] - nz*0.9]); triP(o, Bk[1], Bk[0], Bk[2]); quadP(o, P0, Bk[0], Bk[2], P2); quadP(o, P2, Bk[2], Bk[1], P1); }
    B.flush(g); return g; }};
place('hkpedder', ...TGT.hkpedder);

