// Lo Pan Temple, 15 Ching Lin Terrace, Kennedy Town (first built 1884, rebuilt on the site 1928; declared a monument 2024; murals, plaster
// mouldings, wood carvings, Shiwan ridge pottery and rare stepped gable walls; info.gov.hk press release 10 Oct 2024).
// LandsD rings: temple base 38.3 top 48.7 mPD (10.4 m to the ridge ornament), the Kwong Yuet Tong public office beside it 8.1 m. Two halls with
// ridges across the plan, front towards the north-west (downhill), tile colour and the abstract ridge figures are approximations.
LANDMARKS.hklopan = {zh:'鲁班先师庙', en:'Lo Pan Temple', cat:'old', r:19, h:11,
  lt:{m:0, c:'#ffd29a', k:0.95, e:0.45, anim:'breathe'},
  build(){
    const g = new THREE.Group(), B = mkB(), Z = mkZ('hklopan', 't'), T = D.hklopan, y0 = Z.g0, yt = Z.top('t');
    const BK = '#8f8e88', GN = '#c9c3b5', RT = '#3f7254', RD = '#9c3a2c', GOLD = '#c9a24a', CER = ['#3d8a6a', '#c9a24a', '#b24a34', '#3a6ea8', '#e0d6b8'];
    const P = T.t, ob = obE(P), dir = (ob.c*-0.63 + ob.s*-0.78) > 0 ? 1 : -1, uF = dir*ob.L/2; // front end (north-west)
    found(B, FDN, P, Z, y0);
    prismP(B.p(GN), P, y0, y0 + 0.8, true); prismP(B.p(BK), P, y0 + 0.8, y0 + 6.2, true);
    const halls = [[-ob.L/2, -ob.L/2 + ob.L*0.42], [ob.L/2 - ob.L*0.48, ob.L/2]];
    for (const [u0, u1] of halls){ gableO(B.p(RT), ob, u0 - 0.6, u1 + 0.6, -ob.W/2 - 0.7, ob.W/2 + 0.7, y0 + 6.2, yt - 1.6 - y0 - 6.2, false, B.p(BK));
      ribsO(B.p('#2f5e44'), ob, u0 - 0.6, u1 + 0.6, -ob.W/2 - 0.7, ob.W/2 + 0.7, y0 + 6.2, yt - 1.6 - y0 - 6.2, false, 0.6);
      const uc = (u0 + u1)/2, hw = (u1 - u0)/2 + 0.6, rr = yt - 1.6 - y0 - 6.2; boxO(B.p(GN), ob, uc - 0.35, uc + 0.35, -ob.W/2 - 0.6, ob.W/2 + 0.6, yt - 1.7, yt - 1.2);
      // stepped gable walls on both sides, standing proud of the roof
      for (const sv of [-1, 1]) for (const [f, t] of [[1, 0.42], [0.68, 0.78], [0.36, 1.12]]){ boxO(B.p(BK), ob, uc - hw*f, uc + hw*f, sv*ob.W/2 - 0.22 + sv*0.5, sv*ob.W/2 + 0.22 + sv*0.5, y0 + 6.0, y0 + 6.2 + rr*t); boxO(B.p(GN), ob, uc - hw*f - 0.1, uc + hw*f + 0.1, sv*ob.W/2 - 0.3 + sv*0.5, sv*ob.W/2 + 0.3 + sv*0.5, y0 + 6.2 + rr*t, y0 + 6.4 + rr*t); }
      const n = 7; for (let k = 0; k < n; k++){ const v = -ob.W/2 + (k + 0.5)/n*ob.W, h = 0.5 + (k % 3)*0.15; boxO(B.p(CER[k % CER.length]), ob, uc - 0.25, uc + 0.25, v - 0.45, v + 0.45, yt - 1.2, yt - 1.2 + h); }
      for (const s of [-1, 1]){ const q = ob.p(uc, s*(ob.W/2 + 0.3)); LCone(g, 0.35, 1.1, q[0], yt - 1.3, q[1], GOLD, 6); } }
    // front: granite door frame, red doors, a painted frieze under the eaves
    { const v0 = -1.2, v1 = 1.2; boxO(B.p(GN), ob, uF - dir*0.25 - 0.15, uF - dir*0.25 + 0.15, v0 - 0.45, v1 + 0.45, y0 + 0.8, y0 + 4.4); boxO(B.p(RD), ob, uF - 0.05, uF + 0.05, v0, v1, y0 + 0.8, y0 + 3.6);
      boxO(B.p('#d8cba8'), ob, uF - 0.06, uF + 0.06, -ob.W/2 + 0.4, ob.W/2 - 0.4, y0 + 4.9, y0 + 6.0); }
    // Kwong Yuet Tong public office: two storeys, plain walls, pitched tile roof
    { const Q = T.o, oq = obE(Q), yq = Z.top('o'); found(B, FDN, Q, Z, y0); prismP(B.p('#d9d2c2'), Q, y0, yq - 2.0, true); winsP(B.p({c:'#3f4844', glow:'#ffd8a6', gk:0.45}), Q, y0 + 1.0, yq - 2.4, 3.1, 2.6, 1.0, 1.7, 0.05);
      gableO(B.p('#4f7a5e'), oq, -oq.L/2 - 0.4, oq.L/2 + 0.4, -oq.W/2 - 0.4, oq.W/2 + 0.4, yq - 2.0, 2.0, true, B.p('#d9d2c2')); }
    B.flush(g); return g; }};
place('hklopan', ...TGT.hklopan);

// Kennedy Town Swimming Pool (Farrells; outdoor pools 2011, indoor pools 2017; zinc-clad "futuristic pool building"; translucent insulated
// membrane roof over the indoor hall; Wikipedia). LandsD ring: base 3.8 top 19.8 mPD (16.0 m). Vault form and the glazed harbour front are
// approximations; the outdoor basins are not modelled.
LANDMARKS.hkktpool = {zh:'坚尼地城游泳池', en:'Kennedy Town Swimming Pool', cat:'new', r:86, h:16,
  lt:{m:0, c:'#e8f2ff', k:0.6, e:0.6},
  build(){
    const g = new THREE.Group(), B = mkB(), Z = mkZ('hkktpool', 'p'), P = D.hkktpool.p, ob = obE(P), y0 = Z.g0, y1 = Z.top('p');
    const ZN = '#8f989c', ZN2 = '#a9b1b4', MB = {c:'#e3e8e4', glow:'#f2f6ff', gk:0.35}, GL = {c:'#4f6a72', m:1};
    found(B, FDN, P, Z, y0);
    const yE = y1 - 4.5, roof = (x, z) => { const v = ob.loc(x, z)[1]/(ob.W/2); return yE + 4.5*Math.max(0, 1 - v*v); };
    prismP(B.p(ZN), P, y0, yE, true);
    bandsP(B.p(ZN2), P, y0, yE, 1.4, 0.5, 0.06);
    // glazed hall front towards the harbour (north) and the entrance side
    for (let i = 0; i < P.length; i++){ const [a, b] = E(P, i), [nx, nz] = outN(P, i); if (nz > -0.5 || Math.hypot(b[0]-a[0], b[1]-a[1]) < 3) continue;
      quadP(B.p(GL), [a[0]+nx*0.08, y0 + 0.6, a[1]+nz*0.08], [b[0]+nx*0.08, y0 + 0.6, b[1]+nz*0.08], [b[0]+nx*0.08, yE - 1.0, b[1]+nz*0.08], [a[0]+nx*0.08, yE - 1.0, a[1]+nz*0.08]); }
    // translucent membrane vault: walls up to the curve and the roof surface
    const Q = offO(P, -0.2); prismP(B.p(ZN), Q, yE, roof, true);
    { const o = B.p(MB), n = 26; const pts = resP(Q, 120); const tri = triang(pts); for (const t of tri) for (const k of t){ const p = pts[k]; o.push(p[0], roof(p[0], p[1]) + 0.05, p[1]); } }
    for (let u = -ob.L/2 + 6; u < ob.L/2 - 3; u += 6){ const L = []; for (let v = -ob.W/2; v <= ob.W/2 + 0.01; v += ob.W/12){ const q = ob.p(u, v); if (inPoly(P, q[0], q[1])) L.push(q); } if (L.length > 1) lineP(B.p(ZN2), L, roof, 0.16, 3); }
    B.flush(g); return g; }};
place('hkktpool', ...TGT.hkktpool);

// Sai Ying Pun Community Complex, 2 High Street (2001), behind the retained granite colonnaded facade of the Old Mental Hospital (1892), per the
// phase-1 note. LandsD rings: podium base 43.0 top 64.5 mPD, the block above it to 84.1, the facade range along High Street 41.6-58.0 and the
// small west piece 47.1-58.0. Arch and column rhythm and colours approximate.
LANDMARKS.hksypcc = {zh:'西营盘社区综合大楼', en:'Sai Ying Pun Community Complex (Old Mental Hospital facade)', cat:'old', r:58, h:42,
  lt:{m:0, c:'#ffe6c0', k:0.85, e:0.45, anim:'breathe'},
  build(){
    const g = new THREE.Group(), B = mkB(), Z = mkZ('hksypcc', 'pod'), T = D.hksypcc;
    const GN = '#c9c1b0', GN2 = '#ddd6c6', WL = '#e4dfd3', GL = {c:'#4c5a60', m:1}, GLW = {c:'#3f4844', glow:'#ffdcae', gk:0.5};
    for (const nm of ['pod', 'w2']){ const P = T[nm], y0 = Z.base(nm), y1 = Z.top(nm); found(B, FDN, P, Z, y0); prismP(B.p(WL), P, y0, y1, true); floorsP(B.p(GL), P, y0 + 1.0, y1 - 0.8, 4.0, 1.8, 0.07); flatP(B.p('#8e8c86'), P, y1); parP(B.p(GN2), P, y1, 1.0, 0.3); }
    { const P = T.tw, y0 = Z.base('tw'), y1 = Z.top('tw'); prismP(B.p(WL), P, y0, y1, true); floorsP(B.p(GL), P, y0 + 0.8, y1 - 0.8, 3.6, 1.9, 0.07); mullP(B.p(GN2), P, y0, y1, 4.2, 0.4, 0.1, null, 0.3); flatP(B.p('#8e8c86'), P, y1); roofT(B, P, y1, {par:GN2, ph:1.1, plant:'#c6c0b4', ins:4, plh:3.5}); }
    // the old hospital range on High Street: two storeys of granite arcades / colonnade with a balustrade and cornice
    { const P = T.w, y0 = Z.base('w'), y1 = Z.top('w'), yG = Math.max(y0, y1 - 15.0); found(B, FDN, P, Z, yG); prismP(B.p(GN), P, Math.min(y0, yG), yG, true);
      prismP(B.p('#6c6a64'), offO(P, -1.6), yG, y1 - 1.2, true);
      const i = edgeTo(P, 0, -1, 20), [a, b] = E(P, i); OUTS = area2(P) > 0 ? 1 : -1;
      arcadeP(B.p(GN), B.p(GLW), a, b, yG, yG + 7.0, Math.max(4, Math.round(Math.hypot(b[0]-a[0], b[1]-a[1])/3.6)), 4.6, 0.9, 0.9, 'r');
      colonP(B.p(GN2), B.p(GN), a, b, yG + 7.0, y1 - 1.6, 3.6, 0.01, 0.3, true);
      OUTS = 1; prismP(B.p(GN2), offO(P, 0.2), y1 - 1.6, y1 - 0.9); parP(B.p(GN2), P, y1 - 0.9, 0.9, 0.3); flatP(B.p('#8e8c86'), P, y1 - 1.2); }
    B.flush(g); return g; }};
place('hksypcc', ...TGT.hksypcc);

// The Cenotaph, Chater Road (unveiled 1923; built in stone; an almost exact replica of Lutyens' Cenotaph on Whitehall; Wikipedia). On the OSM
// memorial outline w737551130 (5.2 x 3.1 m). No published height: the pylon is proportioned on the Whitehall original and its height (about
// 10.5 m) is an estimate. No inscriptions are modelled.
LANDMARKS.hkcenotaph = {zh:'和平纪念碑', en:'The Cenotaph', cat:'old', r:15, h:11,
  lt:{m:0, c:'#fff2dc', k:0.95, e:0.5},
  build(){
    const g = new THREE.Group(), B = mkB(), G = G0('hkcenotaph'), P = D.hkcenotaph.p, ob = obE(P), y0 = gMin(G, P) + 0.05;
    const ST = '#e3ded2', ST2 = '#d4cec0';
    found(B, FDN, P, {foot:(Q, y) => Math.min(gMin(G, Q), y) - 2}, y0);
    // three steps on the outline, then the tapering stepped pylon, the tomb chest on top
    let L = ob.L, W = ob.W, y = y0; const box = (l, w, h, c) => { boxO(B.p(c), ob, -l/2, l/2, -w/2, w/2, y, y + h); y += h; };
    box(L, W, 0.3, ST2); box(L - 0.6, W - 0.5, 0.3, ST2); box(L - 1.1, W - 0.9, 0.35, ST2);
    const l0 = L - 1.6, w0 = W - 1.3, H = 7.9, n = 8;
    for (let k = 0; k < n; k++){ const t = k/n, l = l0*(1 - 0.2*t), w = w0*(1 - 0.22*t); boxO(B.p(ST), ob, -l/2, l/2, -w/2, w/2, y + t*H, y + (k + 1)/n*H + 0.01); }
    y += H; box(l0*0.86, w0*0.84, 0.35, ST2); box(l0*0.78, w0*0.7, 0.75, ST); box(l0*0.66, w0*0.5, 0.45, ST2);
    // carved wreath on each long face (stone)
    for (const s of [-1, 1]){ const q = ob.p(0, s*(w0*0.43 + 0.05)); LCyl(g, 0.55, 0.55, 0.12, q[0], y0 + 6.2, q[1], ST2, 14); }
    B.flush(g); return g; }};
place('hkcenotaph', ...TGT.hkcenotaph);

// CCC Hop Yat Church, 2 Bonham Road (1926; Neo-Gothic; a clock tower that "was a local landmark"; Grade I; Wikipedia). LandsD rings: church base
