    const BR = '#9e4634', TR = '#e6dccb', RF = '#5e5550', SG = {c:'#3e3a46', glow:'#ffcf96', gk:0.45};
    found(B, FDN, P, Z, y0);
    prismP(B.p(BR), P, y0, yE, true); bandsP(B.p(TR), P, y0, yE, 3.5, 0.3, 0.07); lineRingP(B.p(TR), P, yE, 0.25, 3);
